using UnityEngine;

// One playable mercenary: its animation frames and how it attacks. Assets live in
// Assets/Characters/ (MeowKnight.asset, Meowolas.asset) and are generated by
// Assets/Editor/LobbySceneBuilder.cs - re-run it after changing which frames to use.
[CreateAssetMenu(menuName = "Cats Smash/Character Definition")]
public class CharacterDefinition : ScriptableObject
{
    public string displayName;
    [Tooltip("Job (검사 / 궁수) - kept for data; the lounge shows tagName instead.")]
    public string jobName;
    [Tooltip("Shown above the wandering cat and as the lounge panel title (하양이 / 치즈).")]
    public string tagName;
    [Tooltip("Short attack line (e.g. 근접 · 검으로 베기).")]
    public string role;
    [Tooltip("Role group badge in the lobby panel (e.g. 근거리 전사 / 원거리 사수).")]
    public string roleGroup;
    public Color roleColor = UiTheme.Wine;
    [TextArea(2, 4)]
    [Tooltip("Character description shown when the cat is picked in the lobby.")]
    public string description;

    [Header("Animation frames")]
    public Sprite[] idleFrames;
    public Sprite[] runFrames;
    public Sprite[] attackFrames;
    public Sprite[] damageFrames;
    public Sprite[] jumpFrames;
    public Sprite[] deathFrames;
    [Tooltip("Roll animation (shown on the loading screen).")]
    public Sprite[] dodgeFrames;
    public float dodgeFramesPerSecond = 12f;
    public float framesPerSecond = 8f;
    public float attackFramesPerSecond = 8f;
    public float damageFramesPerSecond = 10f;
    public float jumpFramesPerSecond = 16f;
    public float deathFramesPerSecond = 8f;

    [Header("Attack")]
    [Tooltip("Melee combo: each click continues to the next move (wraps after the last). Empty = single attackFrames swing.")]
    public AttackMove[] combo;
    [Tooltip("Seconds after a move finishes during which a click still continues the combo.")]
    public float comboWindow = 0.35f;
    [Tooltip("Clicking in the air: hold these frames while diving straight down...")]
    public Sprite[] jumpAttackFallFrames;
    [Tooltip("...then play this move on landing (its frames are the impact). Empty frames = no jump attack.")]
    public AttackMove jumpAttack;
    [Tooltip("Off = melee swing in front of the player. On = fires projectileSprite toward the mouse.")]
    public bool ranged;
    [Tooltip("Extra max hearts for this mercenary (the melee knight has to take hits to deal them).")]
    public float bonusMaxHP;
    public Sprite projectileSprite;
    public float projectileSpeed = 16f;
    public float projectileRange = 14f;
    [Tooltip("Seconds into the attack animation when the arrow leaves the bow.")]
    public float releaseDelay = 0.35f;

    // ---- Frame alignment (filled in by the editor's CharacterAssets builder) ----
    [Tooltip("All frames come from one canvas with a shared pivot at the body centre (AsepriteFrames), so they line up as-is.")]
    public bool canvasAligned;
    // Every frame in these sheets is trimmed to its own bounding box (pivot at that box's
    // center), so a sword/bow/tail sticking out changes where the body lands. The builder slides each frame left/right until its body pixels best match
    // Idle frame 0 (feet kept on the ground) and stores that shift here, in sprite units.
    [HideInInspector] public Sprite[] alignSprites;
    [HideInInspector] public float[] alignOffsetsX;
    [HideInInspector] public Vector2 alignReferenceSize;
    [HideInInspector] public int alignVersion;

    System.Collections.Generic.Dictionary<Sprite, float> alignLookup;

    public bool HasAlignment => alignReferenceSize.x > 0f && (canvasAligned || (alignSprites != null && alignSprites.Length > 0));

    // Local position for a `visual` child (with the given uniform scale) so that this
    // frame's body sits centered on the parent, feet at -alignReferenceSize.y/2.
    public bool TryGetVisualOffset(Sprite frame, bool flipX, float scale, out Vector2 localPosition)
    {
        localPosition = Vector2.zero;
        if (!HasAlignment || frame == null) return false;
        // The pivot already is the body centre, and flipX mirrors around it.
        if (canvasAligned) return true;
        if (alignLookup == null)
        {
            alignLookup = new System.Collections.Generic.Dictionary<Sprite, float>();
            for (int i = 0; i < alignSprites.Length && i < alignOffsetsX.Length; i++)
                if (alignSprites[i] != null) alignLookup[alignSprites[i]] = alignOffsetsX[i];
        }
        if (!alignLookup.TryGetValue(frame, out float dx)) return false;

        float halfW = alignReferenceSize.x * 0.5f;
        float halfH = alignReferenceSize.y * 0.5f;
        // The frame's bottom-left corner should land at (dx - halfW, -halfH) relative to the
        // body center. The sprite is drawn around its pivot (these sheets use a centered
        // pivot), and flipX mirrors it around that pivot - so convert accordingly.
        float pw = frame.pivot.x / frame.pixelsPerUnit;
        float ph = frame.pivot.y / frame.pixelsPerUnit;
        float x = flipX ? (halfW - dx - pw) : (dx - halfW + pw);
        float y = ph - halfH;
        localPosition = new Vector2(x * scale, y * scale);
        return true;
    }
}

// One swing of a melee combo. Distances are in sprite units (multiplied by the player's
// visual scale at runtime) so they match the art.
[System.Serializable]
public class AttackMove
{
    public string name;
    public Sprite[] frames;
    public float framesPerSecond = 14f;
    [Tooltip("Frame on which the blade connects and damage is dealt.")]
    public int hitFrame = 1;
    [Tooltip("Frames at the end that are only the return-to-idle; the next combo click cuts them off.")]
    public int recoveryFrames;
    public float damageMultiplier = 1f;
    [Tooltip("How far in front of the body centre the blade reaches (sprite units, read from the art).")]
    public float reach = 0.2f;
    [Tooltip("Also hits enemies behind the player (spin / ground slam).")]
    public bool hitsAllAround;
    [Tooltip("Step forward during the wind-up (sprite units), spread over the frames before the hit.")]
    public float lunge;

    [Header("Ranged moves")]
    [Tooltip("Set = this move shoots (on hitFrame, toward the mouse) instead of hitting in melee. Several frames = animated.")]
    public Sprite[] projectileFrames;
    public float projectileFps = 12f;
    public float projectileSpeedMultiplier = 1f;
    [Tooltip("Flies through enemies, hitting each one once.")]
    public bool projectilePierces;
    [Tooltip("Where the arrow appears, from the body centre when facing right (sprite units).")]
    public Vector2 projectileSpawn;

    public bool IsRanged => projectileFrames != null && projectileFrames.Length > 0;
}
